use crate::config::{Driver, Kind, ServiceConfig};

pub(super) fn svc(name: &str, kind: Kind, driver: Driver, port: u16) -> ServiceConfig {
    ServiceConfig {
        name: name.to_owned(),
        kind,
        driver,
        image: "x".to_owned(),
        host: "127.0.0.1".to_owned(),
        port,
        database: None,
        username: None,
        password: None,
        bucket: None,
        access_key: None,
        secret_key: None,
        api_key: None,
        region: None,
        scheme: None,
        domain: None,
        domains: None,
        resolved_domain: None,
        routes: None,
        container_port: None,
        smtp_port: None,
        volumes: None,
        env: None,
        command: None,
        depends_on: None,
        seed_file: None,
        hook: Vec::new(),
        health_path: None,
        health_statuses: None,
        restart: None,
        localhost_tls: false,
        octane: false,
        octane_workers: None,
        octane_max_requests: None,
        php_extensions: None,
        trust_container_ca: false,
        env_mapping: None,
        javascript: None,
        container_name: None,
        resolved_container_name: None,
        runtime: Default::default(),
    }
}
